"""Article-specific editorial source for CC-09 (Civil Code arts. 611-670)."""
from __future__ import annotations


def row(says, means, example, warning, term, definition, *, target=None, terms=None):
    return {"target": target, "o_que_diz": says, "o_que_significa": means, "exemplo_pratico": example, "atencao": warning, "palavras_dificeis": terms or [{"termo": term, "explicacao": definition}]}


ROWS = {
    "611": row("Na empreitada que inclui materiais, o empreiteiro suporta o risco até entregar a obra aceita pelo dono; a mora deste em recebê-la transfere-lhe o risco.", "Quem fornece execução e insumos conserva o risco do resultado enquanto não ocorre a entrega regular. A recusa ou atraso injustificado do encomendante altera essa distribuição.", "Construtora conclui e oferece obra conforme o ajuste; o dono adia injustificadamente o recebimento e passa a suportar perda fortuita posterior.", "Devem ser apurados entrega, conformidade e mora. Culpa do empreiteiro não fica protegida pela simples mora do dono.", "Empreitada mista", "contrato em que o empreiteiro fornece trabalho e materiais"),
    "612": row("Quando o empreiteiro fornece somente trabalho, os riscos sem culpa dele pertencem ao dono da obra.", "Os materiais e o resultado econômico permanecem na esfera do encomendante, salvo dano causado pelo executor. A regra separa risco fortuito de responsabilidade culposa.", "Pedreiro usa material fornecido pelo proprietário; enchente inevitável destrói o serviço sem culpa do profissional.", "A ausência de culpa precisa ser demonstrada. Imperícia, negligência ou mora do empreiteiro podem alterar a solução.", "Empreitada de lavor", "empreitada em que o contratado fornece apenas mão de obra"),
    "613": row("Na empreitada apenas de trabalho, a perda fortuita antes da entrega normalmente retira do empreiteiro a remuneração; ele a conserva se provar defeito dos materiais e reclamação oportuna.", "O executor assume o risco de não receber pelo resultado perdido, mas não responde pelo material inadequado que denunciou em tempo.", "Marceneiro alerta por escrito que a madeira está comprometida; a peça perece antes da entrega justamente por esse defeito.", "A exceção exige prova conjunta da causa material e da reclamação tempestiva. Mora do dono ou culpa do empreiteiro mudam o enquadramento.", "Retribuição", "remuneração devida pelo trabalho contratado"),
    "614": row("Obra dividida em etapas ou calculada por medida pode ser verificada e paga proporcionalmente. Pagamento ou medição gera presunção de aceitação, esta última após trinta dias sem denúncia de defeito.", "A lei permite recebimento progressivo e cria estabilidade para partes já medidas. O dono conserva prazo para apontar vícios após cada medição.", "Empreiteiro conclui três quilômetros de pavimento, mede a etapa e cobra a fração correspondente.", "As presunções admitem discussão conforme as provas. O silêncio de trinta dias refere-se à medição e não elimina automaticamente responsabilidade legal por vícios ocultos.", "Medição", "verificação da quantidade ou etapa efetivamente executada"),
    "615": row("Obra concluída conforme contrato ou costume local deve ser recebida; o dono pode rejeitá-la se houver desvio das instruções, do projeto ou das regras técnicas.", "O recebimento é dever quando o resultado corresponde ao combinado. Desconformidade relevante permite recusa em vez de impor ao dono trabalho inadequado.", "Cobertura segue projeto e técnica aplicável, obrigando o recebimento; estrutura executada fora do cálculo pode ser rejeitada.", "Nem toda imperfeição autoriza rejeição total. Gravidade, possibilidade de correção e alternativa de abatimento devem ser avaliadas.", "Regras técnicas", "padrões profissionais de segurança e qualidade aplicáveis à obra"),
    "616": row("Diante de obra desconforme, quem a encomendou pode aceitá-la com redução do preço, em vez de rejeitá-la.", "O dono dispõe de alternativa para conservar um resultado ainda útil e ajustar a remuneração à perda de valor ou qualidade.", "Armários foram feitos com acabamento inferior, mas continuam utilizáveis; o cliente os recebe com abatimento proporcional.", "Recebimento com abatimento não deve gerar dupla reparação pelo mesmo defeito. Danos autônomos exigem demonstração própria.", "Abatimento", "redução do preço em proporção à desconformidade"),
    "617": row("O empreiteiro deve pagar pelos materiais recebidos que inutilizar por imperícia ou negligência.", "Embora o dono forneça os insumos, o executor responde quando sua atuação tecnicamente inadequada ou descuidada causa a perda.", "Profissional aplica produto incompatível e inutiliza revestimento entregue pelo cliente.", "Perda fortuita sem culpa segue outra distribuição de riscos. É necessário provar dano, culpa e relação causal.", "Imperícia", "falta de conhecimento ou habilidade técnica exigível"),
    "618": row("Em construções relevantes, quem fornece materiais e execução responde por cinco anos pela solidez e segurança decorrentes do solo ou dos insumos; o dono deve agir em cento e oitenta dias após descobrir o defeito.", "Há garantia legal mínima para falhas estruturais graves, acompanhada de prazo para exercício da pretensão após o aparecimento do vício.", "Fissura estrutural surge no terceiro ano; o proprietário identifica o defeito e toma providência judicial dentro de cento e oitenta dias.", "Os cinco anos e os cento e oitenta dias têm funções distintas. A norma exige obra considerável e problema ligado à solidez ou segurança.", "Prazo de garantia", "período em que o construtor responde pela estabilidade e segurança previstas em lei"),
    "619": row("Preço de obra executada segundo projeto aceito não aumenta por alterações, salvo instrução escrita do dono; mesmo sem escrito, este paga mudanças que acompanhou continuamente sem protestar.", "A regra protege o preço contratado, mas impede que o encomendante aceite conscientemente acréscimos e depois negue pagamento.", "Proprietário visita diariamente ampliação evidente, não se opõe e depois é cobrado pelo custo arbitrado.", "A exceção depende de presença reiterada, impossibilidade de ignorar a mudança e ausência de protesto. Autorização escrita continua a prova preferível.", "Arbitramento", "fixação do valor por critério técnico ou decisão competente"),
    "620": row("Queda superior a dez por cento no custo de material ou mão de obra permite ao dono pedir revisão do preço global e obter a diferença apurada.", "A redução extraordinária do custo pode beneficiar o encomendante, evitando que o preço permaneça desproporcionalmente acima da execução.", "Após contratação, insumos e trabalho ficam quinze por cento mais baratos; o dono solicita recálculo comprovado.", "A revisão não é automática e exige redução superior ao limite legal, comparação verificável e pedido do interessado.", "Preço global", "valor total ajustado para a obra como conjunto"),
    "621": row("O proprietário não pode alterar projeto aprovado sem consentimento do autor, salvo inconveniência ou custo excessivo superveniente comprovado; pequenas mudanças preservando a unidade estética ficam fora da proibição.", "A norma protege a integridade da criação, mas admite adaptação tecnicamente necessária ou economicamente justificável.", "Mudança geológica torna solução original excessivamente cara e exige alteração comprovada por avaliação técnica.", "Ser dono da obra não elimina direitos do autor do projeto. Alteração de pouca monta ainda deve respeitar a unidade estética.", "Unidade estética", "coerência visual e conceitual do projeto como um todo"),
    "622": row("Se terceiro executa a obra e o autor do projeto não dirige nem fiscaliza, a responsabilidade deste limita-se aos danos por defeitos estruturais previstos na garantia legal.", "Projetar não equivale a controlar a execução. Sem assumir direção ou fiscalização, o autor responde apenas no âmbito ligado aos defeitos do próprio projeto abrangidos pela regra legal.", "Arquiteto entrega projeto, mas outra empresa executa e fiscaliza; falha puramente executiva não lhe é automaticamente atribuída.", "É preciso separar defeito de projeto, erro de execução e dever contratual de fiscalização. A limitação depende de o projetista não ter assumido funções adicionais.", "Direção da obra", "coordenação técnica da execução do projeto"),
    "623": row("O dono pode suspender obra já iniciada, mas deve pagar despesas e lucros do trabalho feito, além de indenização razoável pelo ganho frustrado da parte restante.", "A faculdade de interromper não transfere ao empreiteiro o prejuízo da decisão unilateral do encomendante.", "Empresa cancela construção no meio e remunera etapas executadas, custos incorridos e parcela razoável do lucro esperado.", "A indenização não corresponde necessariamente ao preço integral restante; deve considerar custos evitados e ganho efetivamente perdido.", "Lucro frustrado", "ganho provável que deixou de existir por causa da interrupção"),
    "624": row("Empreiteiro que interrompe a execução sem justa causa responde pelos prejuízos.", "A paralisação injustificada constitui inadimplemento e gera dever de reparar danos causalmente ligados ao abandono.", "Construtora deixa o canteiro sem motivo e o dono paga mais para contratar substituta.", "Suspensão autorizada pelo artigo seguinte não é ilícita. A indenização exige demonstração dos prejuízos e do nexo causal.", "Justa causa", "motivo juridicamente suficiente para suspender o cumprimento"),
    "625": row("O empreiteiro pode suspender por culpa do dono, força maior, dificuldade imprevisível que torne a obra excessivamente cara sem reajuste aceito, ou modificação desproporcional exigida pelo encomendante.", "A lei protege o executor contra impedimentos não assumidos e mudanças que rompem a base econômica ou técnica do projeto.", "Condição geológica inesperada exige solução muito mais cara; o dono rejeita reajuste inerente e o empreiteiro suspende.", "A dificuldade deve ser imprevisível e relevante. A mera redução de lucro ou discordância comum não basta.", "Dificuldade geológica", "obstáculo do solo não previsível que altera a execução planejada"),
    "626": row("A morte de uma das partes não encerra a empreitada, salvo contratação baseada nas qualidades pessoais do empreiteiro.", "Em regra, direitos e deveres patrimoniais continuam com sucessores. A exceção ocorre quando a pessoa específica do executor foi determinante.", "Empresa contratada continua obra apesar da morte do proprietário; já obra artística pessoal pode terminar com a morte do autor escolhido.", "A natureza personalíssima deve resultar do ajuste ou das circunstâncias, não ser presumida em toda empreitada.", "Contrato personalíssimo", "contrato cuja execução depende das qualidades únicas de determinada pessoa"),
    "627": row("No depósito, alguém recebe bem móvel para guardá-lo e devolvê-lo quando o depositante pedir.", "A finalidade central é custódia, não uso, consumo ou transferência de propriedade. O depositário deve conservar e restituir a própria coisa.", "Pessoa entrega joia a empresa de guarda até solicitar sua devolução.", "Depósito difere de comodato: o depositário não recebe a coisa para utilizá-la. Bens fungíveis com devolução equivalente seguem regra própria.", "Depositário", "quem recebe a coisa para guardar e devolver"),
    "628": row("O depósito é normalmente gratuito, mas pode ser remunerado por acordo, atividade empresarial ou profissão; sem valor definido, usam-se costumes locais ou arbitramento.", "A gratuidade é presunção, afastada quando a custódia integra atividade econômica ou foi pactuada como onerosa.", "Guarda profissional de móveis é remunerada mesmo sem cláusula de gratuidade; o preço omisso pode ser apurado pelos usos.", "A remuneração não transforma a custódia em locação. Devem ser verificados contrato, atividade e prática local.", "Depósito oneroso", "custódia em que o depositário recebe remuneração"),
    "629": row("O depositário deve guardar a coisa com o mesmo cuidado usado nos próprios bens e devolvê-la, com frutos e acréscimos, quando exigido.", "Há dever de conservação diligente e restituição integral do que foi recebido e do que a coisa produziu.", "Animal deixado em guarda gera cria; o depositário conserva ambos e os entrega ao proprietário.", "O padrão de cuidado pessoal não autoriza negligência. Regras de força maior e despesas necessárias também devem ser consideradas.", "Frutos", "utilidades periodicamente produzidas pela coisa sem destruir sua substância"),
    "630": row("Objeto recebido fechado, selado ou lacrado deve permanecer no mesmo estado.", "O depositário não pode romper invólucro que sinaliza reserva e integridade do conteúdo.", "Envelope lacrado entregue para custódia deve ser devolvido sem abertura.", "Necessidade emergencial de preservação pode exigir análise específica, mas curiosidade ou conveniência não legitimam violação do lacre.", "Lacre", "fecho que evidencia abertura ou violação do objeto"),
    "631": row("Salvo ajuste diferente, a coisa é devolvida onde deveria permanecer guardada, e o depositante paga as despesas da restituição.", "A lei fixa local padrão e atribui o custo de devolução ao titular que pede a coisa.", "Equipamento guardado em armazém é retirado ali; transporte solicitado pelo dono corre por conta dele.", "Contrato ou circunstâncias podem fixar outro local. Despesas causadas por culpa do depositário não se confundem com custo normal de restituição.", "Restituição", "devolução da própria coisa ao legitimado"),
    "632": row("Se a coisa foi depositada também no interesse de terceiro e o depositário foi informado, não pode devolvê-la ao depositante sem consentimento desse beneficiário.", "A ciência do interesse alheio limita a faculdade de retomada do depositante e protege a finalidade compartilhada da custódia.", "Documento fica em guarda para garantir comprador; o vendedor não pode retirá-lo sozinho após o depositário ser avisado.", "O impedimento depende de interesse do terceiro e comunicação ao depositário. Não basta alegação desconhecida no momento da devolução.", "Terceiro interessado", "pessoa distinta das partes cuja posição é protegida pelo depósito"),
    "633": row("Mesmo com prazo, a coisa deve ser devolvida quando pedida, salvo retenção legal, embargo, execução notificada ou suspeita razoável de obtenção dolosa.", "A disponibilidade do depositante prevalece sobre o prazo, mas situações de segurança jurídica autorizam recusa temporária.", "Depositário recebe ordem de execução sobre o bem e não o entrega ao depositante enquanto a constrição vigora.", "A recusa exige enquadramento real em uma exceção. Suspeita de origem dolosa conduz ao procedimento do artigo seguinte, não à apropriação da coisa.", "Embargo", "restrição judicial que impede livre entrega ou disposição do bem"),
    "634": row("Havendo suspeita fundada de obtenção dolosa, o depositário deve expor o motivo e pedir recolhimento ao depósito público.", "Em vez de escolher entre possíveis titulares ou conservar indefinidamente o bem, ele o entrega à custódia institucional sob controle competente.", "Depositário descobre indícios de furto e requer que o objeto seja recolhido oficialmente.", "A suspeita precisa ser razoável e fundamentada. O depositário não adquire direito sobre a coisa nem pode simplesmente entregá-la a terceiro.", "Depósito público", "custódia oficial de bem submetido a dúvida ou medida jurídica"),
    "635": row("Depositário impossibilitado de continuar a guarda por motivo plausível pode pedir depósito judicial quando o depositante não aceita a devolução.", "A medida permite exoneração segura sem abandonar o objeto nem permanecer vinculado contra situação justificável.", "Armazém será interditado e o proprietário recusa retirar o bem; o guardião requer custódia judicial.", "Conveniência simples pode ser insuficiente. Devem existir motivo plausível, tentativa de devolução e recusa do depositante.", "Depósito judicial", "entrega do bem à custódia determinada pelo Judiciário"),
    "636": row("Se força maior destrói a coisa e o depositário recebe substituição, deve entregá-la ao depositante e transferir as ações contra o responsável.", "A vantagem que ocupa o lugar do bem pertence ao titular, assim como os direitos de cobrança ligados à perda.", "Carga guardada perece e seguradora paga indenização ao depositário; o valor e direitos correspondentes são repassados ao dono.", "A escusa depende de força maior provada. A regra não autoriza reter indenização nem elimina responsabilidade por culpa concorrente.", "Sub-rogação real", "substituição econômica de um bem por outro valor ou direito"),
    "637": row("Herdeiro que, de boa-fé, vende coisa depositada deve ajudar o depositante a recuperá-la e devolver ao comprador o preço recebido.", "A boa-fé afasta tratamento de apropriação consciente, mas impõe cooperação para restauração das posições envolvidas.", "Herdeiro desconhece o depósito, vende quadro e depois auxilia o dono na reivindicação, restituindo o preço ao adquirente.", "Má-fé ou impossibilidade de recuperação pode gerar consequências diferentes. O artigo não transfere propriedade ao herdeiro.", "Reivindicação", "pedido do proprietário para recuperar coisa que está com terceiro"),
    "638": row("Fora das exceções legais, o depositário não pode negar devolução alegando que o depositante não é dono nem compensar dívida, salvo crédito fundado em outro depósito.", "A custódia não permite discutir livremente domínio ou usar a coisa como pagamento de obrigações estranhas.", "Guardião deve devolver equipamento recebido, ainda que alegue dívida comercial sem relação com outro depósito.", "Embargo, suspeita de origem dolosa e retenção legal seguem regimes próprios. A exceção de compensação é restrita.", "Compensação", "extinção recíproca de dívidas entre as mesmas partes"),
    "639": row("Com vários depositantes e coisa divisível, cada um recebe somente sua parte, salvo solidariedade entre eles.", "A devolução acompanha a titularidade fracionada e evita que um depositante retire a parcela alheia.", "Três produtores depositam grãos separados por quotas; cada um retira apenas a sua quantidade.", "Indivisibilidade ou solidariedade altera a entrega. O depositário deve identificar quotas e legitimidade antes de restituir.", "Solidariedade ativa", "situação em que cada credor pode exigir a prestação inteira"),
    "640": row("Sem autorização expressa, o depositário não pode usar a coisa nem confiá-la a outro; autorizado a subdepositar, responde por culpa na escolha do terceiro.", "A guarda é pessoal e não concede fruição. A autorização reduz a responsabilidade, mas mantém dever de selecionar custodiante adequado.", "Guardião autorizado contrata armazém notoriamente inseguro e responde pelos danos ligados à escolha.", "Uso ou subdepósito não autorizado pode gerar perdas e danos. Mesmo autorizado, negligência na seleção permanece relevante.", "Subdepósito", "entrega da coisa guardada a outro depositário"),
    "641": row("Se o depositário se torna incapaz, o administrador de seus bens deve devolver imediatamente a coisa ou encaminhá-la à custódia pública ou a novo depositário.", "A incapacidade não deixa o bem sem proteção; o representante assume dever urgente de regularizar a guarda.", "Após incapacidade do guardião, curador tenta devolver o objeto e, diante de recusa, pede nova custódia.", "A coisa depositada não integra livremente o patrimônio do incapaz. A medida adequada depende da possibilidade de recebimento pelo depositante.", "Administrador de bens", "pessoa legalmente encarregada de gerir patrimônio alheio"),
    "642": row("Força maior exclui a responsabilidade do depositário somente quando ele a prova.", "O evento inevitável pode afastar o dever de indenizar, mas o ônus de demonstrar fato e relação com a perda pertence ao guardião.", "Enchente excepcional destrói depósito seguro; o depositário apresenta provas do evento e das medidas de cuidado.", "A alegação genérica não basta. Culpa, mora ou falta de cautela podem impedir a escusa.", "Força maior", "evento inevitável e alheio que impede o cumprimento"),
    "643": row("O depositante deve reembolsar despesas feitas com a coisa e prejuízos que a própria custódia causar ao depositário.", "Quem entrega o bem suporta custos necessários de conservação e danos inerentes ao depósito que não sejam culpa do guardião.", "Animal em guarda exige tratamento veterinário urgente; o dono reembolsa o gasto comprovado.", "Despesas supérfluas ou prejuízos causados por culpa do depositário não entram automaticamente na regra.", "Despesa necessária", "gasto indispensável para conservar a coisa ou evitar dano"),
    "644": row("O depositário pode reter a coisa até receber remuneração, despesas líquidas ou prejuízos comprovados; se o valor for incerto, pode exigir caução ou remoção para depósito público.", "A retenção garante créditos ligados à custódia, mas exige prova imediata. Dívida ilíquida não autoriza retenção indefinida sem garantia ou custódia alternativa.", "Armazém conserva máquina até pagamento de custo comprovado; gasto controvertido leva a caução e remoção oficial.", "O direito alcança créditos vinculados ao depósito. Apropriação ou venda unilateral da coisa não é autorizada.", "Direito de retenção", "faculdade de conservar a coisa até satisfação de crédito relacionado"),
    "645": row("Depósito de coisas fungíveis com obrigação de devolver equivalente do mesmo gênero, qualidade e quantidade segue as regras do mútuo.", "Como não se exige a mesma unidade recebida, a relação aproxima-se de empréstimo de consumo e transfere os riscos próprios desse regime.", "Pessoa deposita mil litros de combustível autorizando mistura e recebe depois igual quantidade e qualidade.", "Se as unidades devem permanecer separadas e ser devolvidas exatamente, pode existir depósito comum, não irregular.", "Depósito irregular", "custódia de fungíveis com restituição por equivalente"),
    "646": row("O depósito voluntário deve ser provado por escrito.", "A lei exige documentação para demonstrar a existência da custódia escolhida pelas partes.", "Recibo identifica bem, depositante e guardião e serve para provar o depósito.", "A regra é probatória e não autoriza falsificar formalidade inexistente. Depósito necessário possui disciplina de prova diferente.", "Prova escrita", "documento capaz de demonstrar a relação jurídica"),
    "647": row("É necessário o depósito imposto por lei ou realizado durante calamidade, como incêndio, inundação, naufrágio ou saque.", "Nessas situações, a custódia nasce de dever normativo ou urgência, sem a liberdade típica do depósito voluntário.", "Durante enchente, morador entrega bens a vizinho para salvá-los, configurando depósito necessário.", "A lista de calamidades é exemplificativa, mas deve haver situação equivalente. O regime aplicável continua nos artigos seguintes.", "Depósito necessário", "custódia decorrente de obrigação legal ou situação emergencial"),
    "648": row("Depósito imposto por lei segue a norma específica e, nas lacunas, as regras do voluntário; o depósito de calamidade admite qualquer meio de prova.", "A lei especial tem prioridade. A urgência justifica flexibilidade probatória porque documento pode ser inviável no momento.", "Bem entregue durante incêndio é provado por testemunhas e registros, mesmo sem recibo.", "Liberdade de prova não dispensa demonstração convincente da entrega e do objeto. Regras especiais podem estabelecer requisitos adicionais.", "Meio de prova", "instrumento lícito usado para demonstrar um fato"),
    "649": row("Bagagem de viajante ou hóspede em hospedaria é equiparada a depósito necessário; o hospedeiro responde também por subtrações praticadas por empregados ou pessoas admitidas no estabelecimento.", "A hospedagem inclui dever reforçado de guarda dos pertences, abrangendo riscos ligados à organização do local.", "Funcionário do hotel furta mala de hóspede e o estabelecimento responde como depositário.", "A responsabilidade pode cessar na hipótese do artigo seguinte. Devem ser provados hospedagem, bem e prejuízo.", "Hospedeiro", "responsável pelo estabelecimento que recebe viajantes ou hóspedes"),
    "650": row("A responsabilidade do hospedeiro cessa se ele provar que o dano aos pertences não poderia ter sido evitado.", "O estabelecimento pode afastar o dever de indenizar demonstrando inevitabilidade real, apesar das cautelas exigíveis.", "Evento externo imprevisível e irresistível destrói bagagens mesmo com medidas adequadas de segurança.", "A prova cabe ao hospedeiro. Falha de vigilância, acesso ou organização impede tratar o fato como inevitável.", "Inevitabilidade", "impossibilidade concreta de impedir o evento com cuidado adequado"),
    "651": row("Depósito necessário não é presumido gratuito; na hospedagem, sua remuneração já integra o preço cobrado.", "A custódia emergencial ou legal pode gerar remuneração, e o hotel não cobra separadamente quando a guarda está incluída na diária.", "Hóspede paga a hospedagem, que já abrange a guarda normal de sua bagagem.", "Serviços extraordinários podem depender de ajuste específico, mas não se presume gratuidade do depósito necessário.", "Remuneração implícita", "pagamento compreendido no preço de outro serviço contratado"),
    "652": row("O texto do Código prevê restituição coercitiva, indenização e prisão limitada para o depositário que retém indevidamente a coisa.", "A obrigação central é devolver o bem quando exigido e reparar o prejuízo da recusa. A consequência pessoal mencionada no dispositivo exige leitura conjunta com normas superiores e a camada jurisprudencial vigente.", "Guardião recusa devolver joia e o titular busca entrega e indenização pelos danos.", "A prisão não deve ser apresentada como automática apenas porque consta do texto legal. Sua aplicabilidade pertence à análise constitucional e jurisprudencial externa ao ENTENDA.", "Restituição coercitiva", "obtenção forçada da devolução por meio jurídico adequado"),
    "653": row("Mandato surge quando alguém recebe poderes para agir em nome de outra pessoa ou administrar seus interesses; a procuração documenta esses poderes.", "O mandato é a relação jurídica, enquanto a procuração é seu instrumento. A atuação representativa produz efeitos conforme os limites conferidos.", "Empresário autoriza procurador a assinar contrato em seu nome.", "Mandato e representação se relacionam, mas não são sinônimos em todas as hipóteses. A origem, forma e extensão dos poderes devem ser verificadas.", "Mandante", "pessoa que confere poderes para atuação em seu nome"),
    "654": row("Pessoa capaz pode outorgar procuração particular assinada, indicando local, partes, data, finalidade e extensão dos poderes; o terceiro pode pedir reconhecimento de firma.", "O instrumento deve permitir identificar quem autoriza, quem age e quais atos estão abrangidos.", "Proprietário assina procuração especificando imóvel e poderes de administração; a contraparte exige firma reconhecida.", "Reconhecimento de firma não substitui poderes especiais nem a forma exigida para o negócio a praticar.", "Outorgante", "pessoa que concede os poderes na procuração"),
    "655": row("Mesmo quando o mandato foi dado por instrumento público, o substabelecimento pode ser feito por instrumento particular.", "A transferência de poderes não precisa repetir automaticamente a forma pública do mandato original.", "Procurador nomeado por escritura transfere parte dos poderes por documento particular assinado.", "A possibilidade formal não elimina proibição, reserva de poderes ou exigência especial aplicável ao ato final.", "Substabelecimento", "transferência de poderes do mandatário para outra pessoa"),
    "656": row("O mandato pode resultar de declaração expressa ou de comportamento, e ser verbal ou escrito.", "A relação admite diversas formas, desde que a lei do ato pretendido não exija formalidade específica.", "Pessoa começa a executar encargo com ciência e concordância do interessado, revelando mandato tácito.", "O artigo seguinte limita a liberdade de forma. Prova do conteúdo e dos limites pode ser difícil em mandato verbal.", "Mandato tácito", "mandato inferido de condutas inequívocas, sem declaração formal"),
    "657": row("A forma do mandato deve acompanhar a exigida para o ato a realizar, e mandato verbal não serve quando o negócio precisa ser escrito.", "Os poderes representativos não podem contornar a formalidade legal do ato principal.", "Venda que exige instrumento escrito não pode apoiar-se apenas em autorização oral.", "A regra trata da outorga de poderes para o ato específico. Instrumento inadequado pode tornar ineficaz a atuação representativa.", "Simetria de forma", "correspondência entre a forma dos poderes e a exigida para o ato"),
    "658": row("O mandato é presumido gratuito, salvo ajuste de pagamento ou atividade profissional lucrativa; no mandato oneroso, valor omisso segue lei, contrato, usos ou arbitramento.", "A atuação ocasional tende a ser gratuita, enquanto o serviço profissional normalmente gera remuneração.", "Corretor profissional recebe mandato ligado à sua atividade e tem remuneração apurada pelos usos quando o contrato é omisso.", "A presunção pode ser afastada pelas circunstâncias. Remuneração não elimina deveres de diligência e prestação de contas.", "Mandato oneroso", "mandato pelo qual o mandatário tem direito a remuneração"),
    "659": row("A aceitação do mandato pode ser demonstrada pelo início de sua execução.", "O mandatário não precisa declarar formalmente concordância quando começa, de modo inequívoco, a cumprir o encargo.", "Procurador recebe documentos e protocola o pedido autorizado, aceitando tacitamente o mandato.", "Atos preparatórios ambíguos podem não bastar. A execução não amplia os poderes além do que foi outorgado.", "Aceitação tácita", "concordância revelada pelo comportamento em vez de palavras"),
    "660": row("O mandato pode limitar-se a um ou vários negócios determinados ou abranger genericamente os interesses do mandante.", "A extensão decorre da outorga: mandato especial individualiza atos; o geral cobre administração ampla dentro dos limites legais.", "Procuração autoriza somente vender um veículo, enquanto outra cobre administração ordinária de vários bens.", "Mandato geral não concede automaticamente poderes para atos de disposição, que exigem autorização especial.", "Mandato especial", "mandato destinado a negócio ou ato determinado"),
    "661": row("Poderes gerais alcançam apenas administração; alienação, hipoteca, transação e atos extraordinários exigem autorização especial e expressa, e poder para transigir não inclui firmar compromisso.", "Atos que dispõem de direitos ou criam riscos relevantes precisam constar claramente da procuração.", "Administrador pode pagar despesas usuais, mas só vende imóvel se houver poder específico.", "Não se deve ampliar poderes por conveniência. Transação e compromisso são atos distintos e demandam autorizações próprias.", "Poder especial", "autorização explícita para ato que excede a administração comum"),
    "662": row("Ato de quem não tem mandato ou excede os poderes é ineficaz para o representado, salvo ratificação expressa ou inequívoca, que retroage ao ato.", "O interessado não fica vinculado sem autorização, mas pode confirmar posteriormente o negócio e assumir seus efeitos desde a origem.", "Pessoa assina compra sem poderes; o suposto mandante depois recebe o bem e confirma inequivocamente o contrato.", "Silêncio isolado não é necessariamente ratificação. Devem ser avaliados conhecimento, conduta inequívoca e integralidade do ato confirmado.", "Ratificação", "confirmação posterior de ato praticado sem poderes suficientes"),
    "663": row("Se o mandatário contrata claramente em nome do mandante, este responde; se age em nome próprio, o mandatário fica pessoalmente obrigado, ainda que o negócio interesse ao mandante.", "A identificação da posição representativa define quem se vincula perante o terceiro.", "Procurador assina indicando o representado, que assume o contrato; se assina como parte própria, responde diretamente.", "Agir por conta alheia não equivale a agir em nome alheio. O terceiro deve poder reconhecer a representação.", "Atuação em nome próprio", "contratação em que o agente aparece como parte perante o terceiro"),
    "664": row("O mandatário pode reter do objeto da operação o necessário para receber créditos decorrentes do mandato.", "A retenção oferece garantia limitada às quantias ligadas ao encargo executado.", "Procurador recebe valor na operação e separa parcela suficiente para despesas e remuneração devidas.", "A retenção deve ser proporcional e vinculada ao mandato. Não autoriza apropriação de excedente nem dispensa prestação de contas.", "Retenção", "conservação temporária de bem ou valor para garantir crédito relacionado"),
    "665": row("Quem ultrapassa ou contraria os poderes atua como gestor de negócios até eventual ratificação do mandante.", "Sem confirmação, o ato não recebe automaticamente os efeitos do mandato e será avaliado pelo regime de gestão sem autorização.", "Procurador autorizado a alugar vende o bem; o proprietário não fica vinculado enquanto não ratificar.", "Excesso de poderes difere de execução defeituosa dentro do mandato. Ratificação pode alterar retroativamente o enquadramento.", "Gestor de negócios", "quem intervém em interesse alheio sem autorização suficiente"),
    "666": row("Pessoa maior de dezesseis e menor de dezoito anos, não emancipada, pode ser mandatária, mas sua responsabilidade perante o mandante segue as limitações das obrigações de menores.", "A capacidade para executar o mandato não elimina a proteção patrimonial própria da idade.", "Adolescente de dezessete anos recebe poderes para ato permitido; eventual cobrança contra ele observa o regime de incapacidade relativa.", "A capacidade do mandante e a validade do ato final continuam submetidas às regras próprias.", "Mandatário relativamente incapaz", "adolescente que pode executar mandato com responsabilidade legalmente limitada"),
    "667": row("O mandatário deve agir com diligência e indenizar culpa própria ou substituição indevida; a responsabilidade pelo substabelecido varia conforme proibição, autorização, escolha e instruções.", "Quanto menor a autorização para substituir, mais ampla a responsabilidade do mandatário. Ratificação pode vincular o mandante a atos antes ineficazes.", "Procurador proibido de substabelecer escolhe terceiro, que causa dano; ele responde conforme o regime agravado.", "Os quatro parágrafos têm hipóteses diferentes. É essencial verificar se havia proibição, permissão expressa ou silêncio e qual foi a causa do dano.", "Culpa na escolha", "falta de cuidado ao selecionar pessoa inadequada para a tarefa"),
    "668": row("O mandatário deve prestar contas e transferir ao mandante todas as vantagens obtidas por causa do encargo.", "Bens, valores e benefícios recebidos no exercício pertencem ao interessado, não ao agente.", "Procurador recebe desconto e restituição ligados ao negócio e os informa e repassa ao mandante.", "Prestação de contas exige documentação e clareza. Vantagem obtida fora do mandato não se inclui apenas por coincidência temporal.", "Prestação de contas", "demonstração organizada de atos, receitas, despesas e resultados da gestão"),
    "669": row("O mandatário não pode compensar prejuízo que causou com vantagem obtida em outro ponto da gestão.", "Cada dano deve ser reparado; resultado positivo independente não apaga a responsabilidade pelo ato culposo.", "Procurador perde valor por negligência e lucra em outra operação; não usa o lucro para eliminar automaticamente o dano.", "O cálculo global de contas pode considerar valores devidos, mas não suprime a identificação e reparação do prejuízo causado.", "Compensação de resultados", "tentativa de neutralizar dano com ganho produzido em operação distinta"),
    "670": row("O mandatário paga juros desde o desvio quando usa em benefício próprio quantias que deveria entregar ao mandante ou aplicar em despesas.", "A apropriação indevida gera encargo imediatamente, sem depender de cobrança posterior.", "Procurador recebe dinheiro para pagar imposto, aplica-o em negócio pessoal e deve juros desde esse uso.", "Além dos juros, outros prejuízos comprovados podem ser devidos. É necessário identificar o momento do abuso.", "Desvio de numerário", "uso pessoal de dinheiro recebido para finalidade alheia"),
}
